    static JSONObject dependencies()throws Exception {JSONObject material=new JSONObject().put("format_version",1).put("id",MATERIAL).put("kind","material_movement").put("movement_kind","consume").put("quantity_decimal","-2").put("unit","Sack").put("customer_id","qa_customer_1").put("billing_customer_id","qa_customer_1");return new JSONObject().put("formatVersion",1).put("authority",new JSONObject().put("mode","LOCAL_ACTIVE").put("invoice_authority","RECONCILED").put("migration_epoch","qa_migration")).put("worklog_allocations_by_invoice",new JSONObject()).put("material_allocations_by_invoice",new JSONObject()).put("material_movements",new JSONObject().put(MATERIAL,material)).put("material_reversals",new JSONObject());}
